CREATE TABLE public.advisory_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), name text NOT NULL CHECK (length(name) BETWEEN 2 AND 100), phone text NOT NULL CHECK (length(phone) BETWEEN 8 AND 20), email text NOT NULL CHECK (length(email) <= 255), current_isapre text NOT NULL CHECK (length(current_isapre) <= 60), contact_time text NOT NULL CHECK (length(contact_time) <= 60), income numeric NOT NULL DEFAULT 0 CHECK (income >= 0), interested_isapre text NOT NULL DEFAULT '' CHECK (length(interested_isapre) <= 60), status text NOT NULL DEFAULT 'Pendiente' CHECK (status IN ('Pendiente','Contactado','Cerrado')), consent boolean NOT NULL CHECK (consent = true));
GRANT ALL ON public.advisory_requests TO service_role;
ALTER TABLE public.advisory_requests ENABLE ROW LEVEL SECURITY;